  ('Great Sippewisset Marsh', 'Lake', 'freshwater'::public.water_type_enum, ST_SetSRID(ST_MakePoint(-70.64010054615723, 41.58717456720799), 4326)::extensions.geography),
  ('Blackmore Pond', 'Lake', 'freshwater'::public.water_type_enum, ST_SetSRID(ST_MakePoint(-70.75198648995163, 41.75642993590154), 4326)::extensions.geography)
) AS v(name, category, water_type, coordinates)
WHERE NOT EXISTS (
  SELECT 1
  FROM public.locations l
  WHERE lower(trim(l.name)) = lower(trim(v.name))
    AND ST_DWithin(
      l.coordinates,
      v.coordinates,
      250
    )
);
